"""Per-landmark data: OSM refs of the real footprint, front compass bearing (deg), eave metres, description."""
# id: (refs, frontBearingWanted, eaveMetres or None, desc)
SKYTREE_SITE = (35.64793, 139.77176)     # the lawn plaza of Harumi Futo Park at the tip of the Harumi wharf (moved into play)
SKYTREE_TRUE = (35.71006, 139.81070)     # Oshiage, Sumida ward (OSM way/288269147)
I = {
'tokyo_tower': (['@tokyo_tower'], 100, 250, "The 1958 broadcasting tower on the hill of Shiba Park, 333 m: an open steel lattice on four splayed legs painted in bands of international orange and white, modelled on the Eiffel Tower but lighter. The two-storey main deck sits at 150 m, the small top deck at 250 m, a slim antenna mast above. The five-storey FootTown block (grey, flat-roofed) fills the space between the legs."),
'tokyo_skytree': (['@skytree'], 315, 497, "The 2012 broadcasting tower, 634 m, the tallest tower in the world: a pale blue-white ('Skytree white') steel lattice round a concrete core, triangular at the base with a 68 m side and turning to a circle by 300 m, two flared observation decks at 350 m and 450 m and a slim gain tower above. MOVED: the real tower stands at Oshiage, 6 km north-east of the map; here it rises from the open lawn of Harumi Futo Park at the tip of the Harumi wharf."),
'azabudai_hills_mori_jp_tower': (['way/1158739441'], 270, 325, "Pelli Clarke & Partners' 2023 tower at Azabudai Hills, 330 m, the tallest building in Japan: a softly rounded square shaft of pale glass that swells slightly and tapers to a domed, petal-like crown split by four vertical seams. It stands over Heatherwick's rolling green-roofed pergola podium in the valley west of Tokyo Tower."),
'toranomon_hills_mori_tower': (['way/390949466', 'way/390949465'], 90, 247, "The 2014 Mori tower built over the Loop Road No. 2 tunnel, 247 m: a blue-green glass slab with knife-edged, faceted corners and a sloped, wedge-cut crown. A lawn garden steps up over the road portal at its foot."),
'toranomon_hills_station_tower': (['way/1158726591'], 90, 266, "OMA's 2023 tower over Toranomon Hills subway station, 266 m: a glass tower whose faces fold along a central vertical band of activity, capped by the glass box of the TOKYO NODE halls with a rooftop infinity pool. A wide pedestrian bridge crosses Sakurada-dori to the Mori Tower."),
'tokyo_midtown_yaesu': (['way/1116244124'], 285, 240, "The 2022 Yaesu Central Tower, 240 m, facing Tokyo Station across Sotobori-dori: a clear-glass tower with gently curved corners and a sail-like curved top, a hotel in its upper floors. Its base holds a bus terminal and a primary school behind a ribbed glass podium."),
'tokiwabashi_tower': (['way/859375772'], 180, 212, "Tokiwabashi Tower of the Tokyo Torch district (2021, 212 m): a crisp rectangular office slab in silver-grey glass with fine vertical fins and stacked terraces cut into its lower corner, north of Tokyo Station beside the Nihonbashi River."),
'marunouchi_building': (['way/145394394'], 105, 180, "The 2002 rebuild of the 'Maru-Biru', 180 m: a glass office tower set back on a stone-clad five-storey podium that recalls the 1923 original, a tall three-bay arched entrance on the Gyoko-dori corner. It frames the station plaza with its near-twin across the avenue."),
'shin_marunouchi_building': (['relation/3816171'], 105, 198, "The 2007 Shin-Marunouchi Building, 198 m, by Michael Hopkins: a slim grey-glass tower on a seven-storey podium of cream stone, bronze and brick with a rounded crown, paired with the Marunouchi Building across Gyoko-dori."),
'jp_tower_kitte': (['way/145394391'], 20, 200, "The 2012 JP Tower, 200 m: a sheer faceted glass tower rising behind the kept white-tiled modernist front of the 1931 Tokyo Central Post Office (now the KITTE mall) with its clock, on the south side of the station plaza."),
'gran_tokyo_north': (['relation/3818454'], 100, 205, "GranTokyo North Tower (2007, 205 m), the north bookend of Tokyo Station's Yaesu side: a tall crystal-clear glass slab by Helmut Jahn over the Daimaru department store, joined to its twin by the long white sail of the GranRoof canopy."),
'gran_tokyo_south': (['way/95274405'], 100, 205, "GranTokyo South Tower (2007, 205 m), the south bookend of the Yaesu side: the same clear, sharp-edged glass slab as the North Tower, standing free at the end of the GranRoof canopy."),
'otemachi_tower': (['way/145397129'], 180, 200, "The 2014 Otemachi Tower, 200 m: a dark, sober glass office tower with a hotel in its top floors; a third of its site is the 'Otemachi Forest', a real transplanted woodland at street level."),
'tokyo_midtown_hibiya': (['way/847361874'], 300, 192, "The 2018 Hibiya Mitsui Tower, 192 m, facing Hibiya Park: a glass tower with softly curved, overlapping faces (the 'dancing tower') above a stone-banded podium with a stepped roof garden and a round plaza."),
'dentsu_building': (['way/151481755'], 315, 210, "Jean Nouvel's 2002 Dentsu headquarters at Shiodome, 213 m: a razor-thin boomerang-plan blade whose ceramic-fritted glass fades from white to dark grey across the curve, with glass lifts running up the sharp north edge. The Caretta Shiodome mall is at its foot."),
'nittele_tower': (['way/151481850'], 0, 193, "Richard Rogers' 2003 Nippon Television tower, 193 m: a boxy glass tower hung inside four huge exposed steel mega-columns with cross-braced frames on the outside, studios in the wide base and the copper Ghibli clock on its deck."),
'shiodome_city_center': (['way/151481757'], 315, 216, "Kevin Roche's 2003 tower, 216 m: a green-glass tower with one long convex face like a full sail and knife-edge ends, standing where Japan's first railway terminus was (the rebuilt old Shimbashi Station is at its foot)."),
'shiodome_media_tower': (['way/151481857'], 270, 172, "The 2003 Kyodo News headquarters, 172 m: a slim tower of dark glass with a gently bowed face, a hotel in its top floors with a tall atrium slot."),
'tokyo_shiodome_building': (['way/151481753'], 110, 173, "The 2005 Tokyo Shiodome Building, 173 m, with the Conrad hotel in its top ten floors: a broad silver-grey glass slab with rounded ends looking over the Hama-rikyu Gardens."),
'kasumigaseki_building': (['way/206266663'], 0, 147, "Japan's first skyscraper (1968, 147 m, 36 floors): a plain rectangular slab with a tight grid of white aluminium mullions over dark glass and a flat top, on a broad paved plaza."),
'kasumigaseki_common_gate': (['way/145660847'], 180, 176, "The west tower of Central Government Building No. 7 (2007, 176 m): a blue-grey glass office tower with a stone-framed base, built with its east twin round the kept 1930s brick Ministry of Education front."),
'sanno_park_tower': (['way/140005220'], 270, 194, "The 2000 Sanno Park Tower, 194 m, beside the Prime Minister's office: a heavy symmetrical tower of grey granite and glass, the centre of each face recessed between corner piers, a flat crown with a tall mast."),
'izumi_garden_tower': (['way/148788622'], 0, 201, "The 2002 Izumi Garden Tower at Roppongi 1-chome, 201 m: a green-glass tower stepped back in tiers at the top, with glass lift shafts climbing its outside over a terraced hillside garden."),
'ark_mori_building': (['way/1378465719'], 0, 153, "The 1986 centre-piece of ARK Hills, 153 m: a broad, chamfered tower of bronze-tinted glass and brown tile with a flat helipad top, on a podium with Suntory Hall's plaza behind."),
'atago_green_hills_mori_tower': (['way/149718440'], 90, 187, "Cesar Pelli's 2001 office tower on the Atago hill, 187 m: a pale glass shaft with rounded corners that opens at the top into a crown of four curved petals; its residential twin (the Forest Tower) stands to the south across the temple grounds."),
'world_trade_center_hamamatsucho': (['way/882217709'], 90, 197, "The World Trade Center Building South Tower (2021) of the Hamamatsucho rebuild beside the station and the monorail terminus: a sheer rectangular tower of silver-blue glass with fine vertical fins; the main tower rising beside it replaces the dark 1970 original."),
'tokyo_port_city_takeshiba': (['way/436096964'], 110, 208, "The 2020 Port City Takeshiba office tower, 208 m: a wide glass slab whose lower eight floors step back toward the bay as planted terraces (the 'Skip Terrace'), linked to Takeshiba pier and Hamamatsucho by a long deck."),
'nec_supertower': (['way/87510456'], 90, 180, "The 1990 NEC headquarters at Mita, 180 m, the 'rocket': a silver metal-and-glass tower that narrows in three stepped tiers, with a great square wind hole through the building above the atrium at the first step."),
'st_lukes_tower': (['way/119563859', 'way/119563864'], 135, 221, "St. Luke's Garden (1994) on the Sumida at Akashicho: the 221 m office tower with a pinched, notched top and the 146 m residence tower, both in pale silver panels, joined high up by a skybridge."),
'the_tokyo_towers_sea': (['way/197996776'], 225, 194, "Sea Tower of The Tokyo Towers (2008, 194 m, 58 floors), the south twin at the tip of Kachidoki: a tall white-and-grey condominium tower with glass balcony bands and rounded corners over the Asashio Canal."),
'the_tokyo_towers_mid': (['way/197996777'], 225, 194, "Mid Tower of The Tokyo Towers (2008, 194 m, 58 floors), the north twin: identical white-and-grey condominium tower with glass balcony bands, joined to the Sea Tower by a low podium."),
'harumi_triton': (['way/179554456', 'way/179554451', 'way/179554453'], 315, 195, "Harumi Island Triton Square (2001): three office towers in a row along the Asashio Canal stepping up 155 / 175 / 195 m (Z, Y, X), pale grey with blue glass and rounded ends, on a shared podium of shops, a concert hall and terraced gardens."),
'river_city_21_a': (['relation/9150245'], 315, 180, "Century Park Tower (1999, 180 m, 54 floors), the tallest of the River City 21 condominium towers on Tsukuda island: a slender cream-and-brown tower with a stepped, lantern-like crown."),
'river_city_21_b': (['way/467706902'], 315, 132, "River Point Tower (1989, 132 m, 40 floors) at the very tip of Tsukuda where the Sumida divides: a triangular-plan condominium tower in cream tile with rounded balconied corners, the first of River City 21's towers."),
'prince_park_tower': (['way/87439168'], 90, 104, "The 2005 Prince Park Tower Tokyo, 104 m, in Shiba Park at the foot of Tokyo Tower: a broad curved hotel slab in warm stone-coloured panels with a glazed crown, set in lawns."),
'fuji_tv_building': (['way/287770734'], 0, 123, "Kenzo Tange's 1996 Fuji Television headquarters on Odaiba, 123 m: two silver towers joined by an open lattice of three levels of sky corridors on giant columns, with a 32 m titanium-clad sphere (the observation room) lodged high in the frame, and a broad stair up to a seventh-floor roof plaza."),
'tokyo_metropolitan_police_hq': (['way/135739164'], 45, 84, "The 1980 Metropolitan Police headquarters at Sakuradamon, 84 m: a wedge-plan block in pale brown tile whose rounded prow faces the palace moat, topped by a cylindrical communications tower bristling with antennas."),
# design-icons
'tokyo_station': (['relation/4856156'], 285, 35, "Tatsuno Kingo's 1914 Marunouchi station building, restored in 2012: a 335 m red-brick front with white granite banding, three storeys under slate roofs, a gabled centre entrance for the Imperial family and an octagonal dome over each of the north and south halls. The platforms and their canopies lie behind, the GranTokyo towers beyond."),
'national_diet_building': (['relation/3361370'], 105, 21, "The 1936 National Diet: a symmetrical granite building 206 m wide, the two chambers in the wings, with a square central tower ending in a stepped pyramid 65 m high over a columned portico. It looks east down a ginkgo avenue to the palace."),
'imperial_palace_nijubashi': (['way/1071262143', 'way/145402321'], 110, None, "The Seimon Ishibashi, the double-arched stone bridge of 1887 with its iron lamps, crossing the moat to the white-walled main gate of the palace; behind it on the high stone rampart stands the two-storey Fushimi-yagura keep with its flanking galleries (extra.keep). The postcard view of the palace from Kokyo Gaien."),
'imperial_palace_kyuden': (['relation/1968066'], 110, None, "The 1968 Imperial Palace: long, low steel-and-concrete halls in traditional form with sweeping copper-green hipped roofs and deep eaves, round courts (the Chowaden with its 160 m balcony faces the east court where the public gathers at New Year). Set in the woods of the western palace grounds."),
'fujimi_yagura': (['way/176109780'], 180, None, "The Fujimi-yagura of Edo Castle (1659): a three-tier white-plastered keep with grey tiled roofs and curved gables, 16 m, on a 15 m rampart of fitted stone at the south corner of the Honmaru."),
'edo_castle_otemon': (['way/617118937'], 80, None, "The Ote-mon, the main gate of Edo Castle and the entrance to the East Gardens: a square masugata court of stone walls entered by a small Korai-mon and turned through the big two-storey white watari-yagura gatehouse, the bridge over the moat in front."),
'kabukiza': (['relation/4859313'], 225, 30, "The Kabuki-za (rebuilt 2013 by Kengo Kuma to the 1924 / 1951 design): a white Momoyama-revival theatre front on Harumi-dori with a great curved karahafu gable over the entrance, tiled hip-and-gable roofs, red lanterns and purple curtains; the plain 145 m Kabukiza Tower with its white lattice rises behind (extra.tower)."),
'wako_ginza': (['way/103509469'], 180, 28, "The 1932 Hattori clock tower (Wako / Seiko House) on the Ginza 4-chome crossing: a neo-Renaissance stone building whose facade curves round the corner, seven storeys, with the square clock tower on top that chimes the hours."),
'ginza_place': (['way/195551651'], 0, 56, "Ginza Place (2016) across the crossing from Wako: an eleven-storey block wrapped in a white lattice of aluminium panels like openwork basketry, with glazed showrooms at the corner."),
'mitsukoshi_ginza': (['way/117923435'], 270, 56, "Ginza Mitsukoshi, the department store on the east corner of the 4-chome crossing: a cream stone block with a glass-and-steel new wing, a lion statue at the door and a roof terrace."),
'zojoji': (['way/751591140'], 95, None, "Zojo-ji, the Tokugawa family temple under Tokyo Tower: the Daiden main hall (1974) with a huge sweeping grey-tiled hip-and-gable roof over white walls and red-brown timberwork, at the head of a stone court; in front on Hibiya-dori stands the Sangedatsumon (1622), a 21 m two-storey vermilion gate (extra.gate)."),
'tsukiji_honganji': (['way/74314559'], 225, 25, "Ito Chuta's 1934 Tsukiji Hongan-ji: a grey granite temple in ancient Indian style, a symmetrical front with a round-arched (chaitya) central roof bearing a lotus motif, stupa-topped bell towers at both ends, broad steps and stone beasts."),
'hie_shrine': (['way/509411457', 'way/509411455'], 100, None, "Hie Shrine on its wooded hill at Nagatacho: a vermilion-and-white shrine hall and gate with green copper roofs round a gravel court, reached by stairs through the distinctive Sanno torii (a torii with a gabled peak) and a tunnel of red torii at the back."),
'atago_shrine': (['way/149712181'], 95, None, "Atago Shrine on the 26 m Atago hill, the highest natural point of the old city: a small red-lacquered gate and timber shrine hall by a carp pond among camphor trees, at the top of the steep 86-step stone 'stairway to success'."),
'tokyo_international_forum': (['way/144508545', 'way/144508541'], 290, 60, "Rafael Vinoly's 1996 Tokyo International Forum: a 60 m high, 207 m long lens-shaped Glass Hall along the railway, its roof a ribbed steel keel like a ship's hull held on two columns, and four graduated cube-shaped halls in grey granite on the west side, a tree-planted granite plaza between."),
'imperial_hotel': (['way/145403144', 'way/145403151'], 290, 55, "The Imperial Hotel facing Hibiya Park: the 1970 main building, a broad cross-plan seventeen-storey block in brown tile, and the 1983 31-storey tower (129 m) of bronze glass behind it."),
'ministry_of_justice_red_brick': (['way/140109089'], 280, 20, "The 1895 Ministry of Justice by Ende and Bockmann: a three-storey German neo-Baroque block of red brick with white stone bands, arcaded loggias, corner pavilions and steep slate mansard roofs with dormers."),
'kantei': (['relation/7826113'], 90, 30, "The 2002 Prime Minister's Office: a low five-storey modern block of glass, steel louvres and stone set in a bamboo garden on the slope above Sanno, flat-roofed and symmetrical."),
'supreme_court_japan': (['relation/19290024'], 30, 37, "Okada Shinichi's 1974 Supreme Court: massive interlocking blocks of rough white Inada granite with slit windows, like a fortress, on the corner of the palace moat."),
'national_theatre': (['way/23974972'], 80, 30, "The 1966 National Theatre: a long dark-brown precast concrete block shaped like an azekura log storehouse (after the Shosoin), with horizontal 'log' bands and a wide flat eave, facing the Hanzo moat."),
'bank_of_japan': (['relation/3069611'], 200, 20, "Tatsuno Kingo's 1896 Bank of Japan head office: a neo-Baroque stone palace round a forecourt with a columned central block under a green copper dome, the later bank buildings attached to the east."),
'mitsukoshi_nihonbashi': (['way/172599549'], 110, 40, "The Nihonbashi Mitsukoshi main store (1914 / 1935): a seven-storey neo-Renaissance stone block with a rusticated base, giant-order pilasters, bronze lions at the door and a roof tower."),
'nihonbashi_bridge': (['way/550689172'], 110, None, "Nihonbashi, the 1911 double-arched granite bridge from which all road distances in Japan are measured, with bronze kirin and lion lamps on its parapets; the Shuto Expressway viaduct runs low over it along the river (roads: expressway)."),
'takashimaya_nihonbashi': (['way/187643809'], 290, 43, "The 1933 Nihonbashi Takashimaya: an eight-storey department store in pale stone mixing Western classicism with Japanese brackets and rafters, a whole block long on Chuo-dori."),
'rainbow_bridge': (['@rainbow'], 30, 52, "The 1993 Rainbow Bridge across the north of Tokyo Bay from Shibaura to Odaiba: a white suspension bridge with two 126 m towers, a 570 m main span (798 m between anchorages) and a double deck: the Shuto Expressway on top, the bay road, the Yurikamome guideway and walkways below. The loop ramp on the Shibaura side winds the lower deck up to height."),
'odaiba_statue_of_liberty': ([('way/1360709259', 6, 6)], 315, None, "The Odaiba Statue of Liberty: a 12.25 m replica (1/7 scale) of verdigris-green bronze on a white stone pedestal on the Odaiba seafront deck, the Rainbow Bridge behind it."),
'aqua_city_odaiba': (['way/328162159'], 0, 40, "Aqua City Odaiba, the long seven-storey shopping mall on the Odaiba seafront beside Fuji TV: stepped terraces and wooden boardwalk decks facing the bay, a glazed atrium."),
'kachidoki_bridge': (['way/549492916'], 225, None, "The 1940 Kachidoki Bridge over the mouth of the Sumida: a double-leaf bascule centre span (now fixed) between stone machinery towers, with a grey steel tied arch on each side."),
'tsukiji_outer_market': (['way/172598657'], 315, None, "The Tsukiji Outer Market: blocks of low two- and three-storey shop-houses, awnings and stalls crowding narrow lanes beside the Namiyoke shrine; the entry stands on the Tsukiji Uogashi market halls (2016) at its south edge."),
'toyosu_market': (['way/629546000'], 0, None, "Toyosu Market (2018), the wholesale fish market that replaced Tsukiji: the Fish Intermediate Wholesale building, a vast pale-grey four-storey box 360 m long with a green roof lawn and ramps, on the Toyosu wharf."),
'hamarikyu_teahouse': (['way/87456655'], 180, None, "The Nakajima-no-ochaya in the Hama-rikyu Gardens: a low cypress-shingled teahouse on an island in the tidal pond, reached by long cypress bridges (the Otsutai-bashi), black pines round the shore."),
'takeshiba_pier': (['way/436096961'], 135, 20, "The Takeshiba Passenger Ship Terminal, where the Izu and Ogasawara island ships sail from: low terminal buildings round a plaza paved like a ship's deck with a tall white mast monument."),
'takanawa_gateway_station': (['way/781446220'], 90, None, "Kengo Kuma's 2020 Takanawa Gateway Station: a great white folded-membrane roof like origami on steel-and-cedar frames over a glazed concourse above the tracks."),
'shimbashi_sl_plaza': ([('way/1434671683', 12, 4)], 0, None, "The C11 292 steam locomotive (1945), black with red wheels, on a short length of track in the plaza outside Shimbashi Station's Hibiya exit: the meeting place of the salarymen's quarter."),
'ginza_six': (['way/488225309'], 135, 56, "GINZA SIX (2017): a block-long luxury mall on Chuo-dori with six tall flagship fronts under a continuous stainless-steel 'eave', offices above and a roof garden."),
}
